def robustness_sum_from_string(string):
    # Initialize variables to track current number, list of numbers, and state
    current_num = ''
    numbers = []
    has_number = False

    # Iterate through each character in the string
    for char in string:
        if char.isdigit():
            current_num += char
            has_number = True
        elif char == '-':
            # Handle negative sign or hyphen separator
            if current_num and current_num != '-':
                numbers.append(int(current_num))
                current_num = ''
                has_number = True
            elif current_num == '-':
                # If we see a '-' immediately after a number, treat as separator
                # But if it's the start, we need to check context. 
                # Assuming '-' acts as a separator between numbers.
                if current_num:
                    numbers.append(int(current_num))
                    current_num = ''
                    has_number = True
                else:
                    current_num = '-'
                    has_number = True
        else:
            # Non-digit, non-hyphen: treat as separator
            if current_num:
                numbers.append(int(current_num))
                current_num = ''
                has_number = True
            else:
                # Reset state if we hit a non-digit while expecting a number
                # This handles cases like "11-14" where '-' is a separator
                if current_num:
                    numbers.append(int(current_num))
                    current_num = ''
                    has_number = True
                else:
                    # If no number was being built, just continue
                    pass

    # Append the last accumulated number if any
    if current_num:
        numbers.append(int(current_num))

    return sum(numbers)
