from math import comb

MOD = 10**9 + 7

def scaling_numRollsToTarget(d, f, target):
    if target < d or target > d * f:
        return 0
    if target == d:
        return 1

    # dp[i][j] = number of ways to get sum j using i dice
    # Using 1D DP array to save space
    dp = [0] * (target + 1)
    dp[0] = 1

    for die in range(1, d + 1):
        new_dp = [0] * (target + 1)
        for current_sum in range(die, target + 1):
            for face in range(1, f + 1):
                if current_sum - face >= 0:
                    new_dp[current_sum] = (new_dp[current_sum] + dp[current_sum - face]) % MOD
        dp = new_dp

    return dp[target]
