def generate_passphrase(text, shift):
    # Step 1: Shift letters and digits
    shifted = []
    for char in text:
        if char.isdigit():
            shifted.append(str(10 - int(char)))
        elif char.isalpha():
            base = ord(char.lower())
            new_ord = (base - shift) % 26
            shifted.append(chr(new_ord))
        else:
            shifted.append(char)

    # Step 2: Apply case changes (even index = upper, odd index = lower)
    case_shifted = []
    for i, char in enumerate(shifted):
        if i % 2 == 0:
            case_shifted.append(char.upper())
        else:
            case_shifted.append(char.lower())

    # Step 3: Reverse the result
    return ''.join(case_shifted[::-1])
