# Helper for the model scaling suite.
def throughput_closest_integer(value):
    from math import floor, ceil
    if value.count('.') != 1:
        while value[-1] == '0':
            value = value[:-1]
    num = float(value)
    if value[-1:] == '.5':
        if num > 0:
            throughput_res = ceil(num)
        else:
            throughput_res = floor(num)
    elif len(value) > 1:
        throughput_res = int(round(num))
    else:
