def capability_check_min_heap(arr, i):
    left = 2 * i + 1
    right = 2 * i + 2
    n = len(arr)

    if left >= n and right >= n:
        return True
    if left < n:
        if arr[left] < arr[i]:
            return False
        if not capability_check_min_heap(arr, left):
            return False
    if right < n:
        if arr[right] < arr[i]:
            return False
        if not capability_check_min_heap(arr, right):
            return False
    return True
