def capability_check_min_heap(arr, i):
    left = 2 * i + 1
    right = 2 * i + 2

    # If left child index is out of bounds, we are at a leaf node (valid)
    if left >= len(arr):
        return True

    # Check left child property
    if arr[i] > arr[left]:
        return False
    # Recursively check left subtree
    if not capability_check_min_heap(arr, left):
        return False

    # Check right child property if it exists
    if right < len(arr):
        if arr[i] > arr[right]:
            return False
        if not capability_check_min_heap(arr, right):
            return False

    return True
```

